<template>
  <span class="orderByParentSpan">
    <span
      class="up-arrow orderBy absolute cursor-pointer"
      :class="is_order_by_selected('asc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="asc"
      @click="OrderBy('asc')"
    ></span>
    <span
      class="down-arrow orderBy absolute cursor-pointer"
      :class="is_order_by_selected('desc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="desc"
      @click="OrderBy('desc')"
    ></span>
  </span>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocMasterDataLookUpStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  mixins: [],
  props: {
    column_name: {
      type: String,
      required: true,
    },
  },
  components: {},
  methods: {
    is_order_by_selected(direction: string) {
      return Boolean(
        this.orderByMap.has(this.column_name) &&
          this.orderByMap.get(this.column_name) == direction,
      );
    },

    OrderBy(direction: string) {
      if (
        this.orderByMap.has(this.column_name) &&
        this.orderByMap.get(this.column_name) == direction
      ) {
        this.orderByMap.delete(this.column_name);
      } else {
        this.orderByMap.set(this.column_name, direction);
      }

      this.saveOrderByColumns(this.master_lookup_type);
      this.triggerApplyFilters();
    },

    triggerApplyFilters() {
      const event = new CustomEvent('ms_search', {});
      document.dispatchEvent(event);
    },
  },
  setup() {
    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const { orderByMap, master_lookup_type } = storeToRefs(
      doc_ms_data_lookup_store,
    );
    const { saveOrderByColumns } = doc_ms_data_lookup_store;
    return {
      master_lookup_type,
      saveOrderByColumns,
      orderByMap,
    };
  },
});
</script>
